ALTER TABLE notification_preferences ADD COLUMN push_enabled BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE notification_devices(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,binding_id UUID NOT NULL DEFAULT gen_random_uuid(),platform TEXT NOT NULL CHECK(platform IN ('web','android')),token TEXT NOT NULL DEFAULT '',subscription JSONB,token_hash TEXT NOT NULL UNIQUE,enabled BOOLEAN NOT NULL DEFAULT true,registered_at TIMESTAMPTZ NOT NULL DEFAULT now(),last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX notification_devices_user ON notification_devices(user_id) WHERE enabled;
CREATE TABLE notification_push_outbox(id BIGSERIAL PRIMARY KEY,notification_id UUID NOT NULL REFERENCES user_notifications(id) ON DELETE CASCADE,device_id UUID NOT NULL REFERENCES notification_devices(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','skipped','failed')),attempts INTEGER NOT NULL DEFAULT 0,next_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(notification_id,device_id));
CREATE INDEX notification_push_pending ON notification_push_outbox(next_at) WHERE status IN ('pending','sending');
